{
  "format": "actually-useful-backup",
  "version": 1,
  "createdAt": "2026-11-04T17:33:10.505Z",
  "editor": {
    "name": "strike ops",
    "files": [
      {
        "name": "index.html",
        "content": "<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width,initial-scale=1">
<title>STRIKE OPS 20</title>
<style>
*{margin:0;padding:0;box-sizing:border-box}
body{overflow:hidden;background:#070b10;color:#eef4f8;font-family:Inter,Arial,sans-serif}
canvas{display:block}

#lobby{position:fixed;inset:0;z-index:50;display:flex;pointer-events:none}
.left{width:min(460px,46vw);padding:36px;display:flex;flex-direction:column;justify-content:space-between;pointer-events:auto}
.brand{font-size:44px;font-weight:900;letter-spacing:4px}
.brand span{color:#ffcc33}
.sub{color:#c8d6e0;margin-top:8px;font-size:14px}
.modes{display:flex;flex-direction:column;gap:10px;margin-top:22px}
.mode{background:rgba(8,14,20,.72);border:1px solid rgba(255,255,255,.12);border-radius:14px;padding:14px;cursor:pointer}
.mode.active{border-color:#ffcc33;background:rgba(255,204,51,.13)}
.mode h3{font-size:16px}
.mode p{font-size:12px;color:#a9bcc9;margin-top:4px}
.row{display:flex;gap:8px;margin-top:14px;flex-wrap:wrap}
.choice{background:rgba(8,14,20,.72);border:1px solid rgba(255,255,255,.12);color:#c8d6e0;padding:9px 13px;border-radius:10px;cursor:pointer;font-weight:800;font-size:13px}
.choice.active{background:#ffcc33;color:#231a03;border-color:#ffcc33}
.deploy{margin-top:22px;width:100%;padding:18px;border:none;border-radius:14px;font-size:20px;font-weight:900;cursor:pointer;background:linear-gradient(90deg,#ffcc33,#ffb02e);color:#231a03}
.netRow{display:flex;gap:8px;margin-top:12px}
.netBtn{flex:1;padding:13px;border:none;border-radius:11px;font-weight:900;cursor:pointer;background:#26333f;color:#dce6ee}
.netBtn.primary{background:#8dffb0;color:#06120b}
#joinCode{flex:1;padding:12px;border-radius:11px;border:1px solid rgba(255,255,255,.18);background:rgba(0,0,0,.35);color:#fff;font-weight:800;letter-spacing:3px;text-transform:uppercase}
#netStatus{margin-top:10px;font-size:12px;color:#8dffb0;min-height:18px}
.right{margin-left:auto;width:min(470px,44vw);padding:36px;display:flex;flex-direction:column;justify-content:center;gap:14px;pointer-events:auto}
.panel{background:rgba(8,14,20,.74);border:1px solid rgba(255,255,255,.12);border-radius:16px;padding:18px}
.panel h2{font-size:17px;color:#ffcc33;margin-bottom:10px}
.small{font-size:12px;color:#a9bcc9}
.weaponName{font-weight:800}
.weaponType{font-size:11px;color:#ffcc33;font-weight:800;letter-spacing:1px}
.mods{font-size:11px;color:#8dffb0;margin-top:3px}
.shop{max-height:250px;overflow:auto;display:flex;flex-direction:column;gap:9px}
.item{display:flex;justify-content:space-between;align-items:center;gap:10px;background:rgba(255,255,255,.05);border:1px solid rgba(255,255,255,.1);border-radius:10px;padding:10px}
.buy{border:none;border-radius:7px;padding:7px 11px;font-weight:800;cursor:pointer;background:#8dffb0;color:#06120b}
.buy:disabled{opacity:.4;cursor:not-allowed}
.buy.ghost{background:#26333f;color:#dce6ee}
.credits{color:#ffcc33;font-weight:900}

#hud{position:fixed;inset:0;z-index:10;pointer-events:none;display:none}
#crosshair{position:absolute;left:50%;top:50%;width:28px;height:28px;transform:translate(-50%,-50%)}
#crosshair i{position:absolute;background:#8dffb0}
#crosshair i:nth-child(1){left:13px;top:0;width:2px;height:8px}
#crosshair i:nth-child(2){left:13px;bottom:0;width:2px;height:8px}
#crosshair i:nth-child(3){top:13px;left:0;width:8px;height:2px}
#crosshair i:nth-child(4){top:13px;right:0;width:8px;height:2px}
.box{position:absolute;background:rgba(5,9,13,.68);border:1px solid rgba(255,255,255,.12);border-radius:10px;padding:9px 13px}
#top{left:50%;top:14px;transform:translateX(-50%);font-size:13px}
#stance{left:20px;top:14px;font-size:12px;color:#a9bcc9}
#hp{left:20px;bottom:20px;width:280px}
#armorBox{left:20px;bottom:78px;width:280px}
.bar{height:9px;background:rgba(255,255,255,.12);border-radius:6px;overflow:hidden;margin-top:5px}
.fill{height:100%;width:100%}
#hpf{background:#8dffb0}
#arf{background:#8fc4ff}
#gun{right:20px;bottom:20px;text-align:right}
#ammo{font-size:31px;font-weight:900;color:#ffcc33}
#gunname{font-size:13px;font-weight:800}
#gunclass{font-size:11px;color:#ffcc33;font-weight:800;letter-spacing:1px}
#feed{position:absolute;right:20px;top:58px;width:360px;font-size:12px;text-align:right}
.feed{background:rgba(5,9,13,.72);border-right:3px solid #ff5d5d;padding:5px 9px;margin-bottom:5px}
#hit{position:absolute;left:50%;top:50%;width:34px;height:34px;transform:translate(-50%,-50%) rotate(45deg);opacity:0}
#hit b{position:absolute;width:12px;height:2px;background:#fff}
#hit b:nth-child(1){left:0;top:0}
#hit b:nth-child(2){right:0;top:0;transform:rotate(90deg)}
#hit b:nth-child(3){left:0;bottom:0}
#hit b:nth-child(4){right:0;bottom:0;transform:rotate(90deg)}
#dmg{position:absolute;inset:0;background:radial-gradient(circle,transparent 42%,rgba(220,25,25,.48));opacity:0}
#damageArrow{position:absolute;left:50%;top:50%;width:230px;height:230px;transform:translate(-50%,-50%);opacity:0}
#damageArrow::before{content:"";position:absolute;left:50%;top:-18px;transform:translateX(-50%);border-left:20px solid transparent;border-right:20px solid transparent;border-bottom:32px solid rgba(255,60,60,.92)}

#end{position:fixed;inset:0;z-index:60;display:none;align-items:center;justify-content:center;background:rgba(3,6,10,.88)}
.endCard{width:min(720px,96vw);background:#0a1117;border:1px solid #26323e;border-radius:18px;padding:34px;text-align:center}
#podium{display:flex;justify-content:center;align-items:flex-end;gap:18px;margin:24px 0;height:200px}
.podiumSpot{width:130px;display:flex;flex-direction:column;align-items:center;justify-content:flex-end}
.podiumName{font-weight:900;margin-bottom:6px}
.podiumKills{font-size:12px;color:#a9bcc9;margin-bottom:6px}
.podiumBlock{width:100%;border-radius:10px 10px 0 0;display:flex;align-items:flex-start;justify-content:center;padding-top:10px;font-weight:900;color:#231a03}
.first{height:150px;background:linear-gradient(180deg,#ffd75e,#d99b17)}
.second{height:110px;background:linear-gradient(180deg,#dfe7ee,#94a3b0)}
.third{height:85px;background:linear-gradient(180deg,#d29a6b,#96603a)}
</style>
</head>
<body>

<div id="lobby">
  <div class="left">
    <div>
      <div class="brand">STRIKE <span>OPS 20</span></div>
      <div class="sub">ADS • Join-code multiplayer • Real knife • Podium</div>

      <div class="modes" id="modeList"></div>
      <div class="row" id="difficultyList"></div>

      <div class="netRow">
        <button class="netBtn primary" id="hostBtn">HOST MATCH</button>
      </div>
      <div class="netRow">
        <input id="joinCode" placeholder="ENTER CODE" maxlength="8">
        <button class="netBtn" id="joinBtn">JOIN</button>
      </div>
      <div id="netStatus"></div>

      <button class="deploy" id="deployBtn">DEPLOY SOLO</button>
    </div>

    <div class="panel">
      <div class="small">CREDITS</div>
      <div class="credits">CR <span id="lobbyCredits">0</span></div>
      <div class="small" id="lobbyOperator" style="margin-top:8px">RANGER</div>
    </div>
  </div>

  <div class="right">
    <div class="panel">
      <h2>Loadout</h2>
      <div class="small weaponName" id="primaryName">PHANTOM-7</div>
      <div class="weaponType" id="primaryType">ASSAULT RIFLE</div>
      <button class="buy ghost" id="primaryBtn" style="margin-top:8px">CHANGE PRIMARY</button>

      <div class="small weaponName" id="secondaryName" style="margin-top:14px">VIPER .45</div>
      <div class="weaponType" id="secondaryType">PISTOL</div>
      <button class="buy ghost" id="secondaryBtn" style="margin-top:8px">CHANGE SECONDARY</button>
    </div>

    <div class="panel">
      <h2>Controls</h2>
      <div class="small">
        WASD move • Shift sprint • Hold C crouch<br>
        Sprint + C slide • Q/E peek • V knife<br>
        Right mouse ADS • Space jump • R reload<br>
        Left mouse fire • 1/2 weapons • Esc lobby
      </div>
    </div>
  </div>
</div>

<div id="hud">
  <div id="crosshair"><i></i><i></i><i></i><i></i></div>
  <div id="hit"><b></b><b></b><b></b><b></b></div>
  <div id="dmg"></div>
  <div id="damageArrow"></div>

  <div class="box" id="top">
    REDLINE DISTRICT •
    ROUND <span id="round">1</span> •
    ENEMIES <span id="enemyLeft">0</span> •
    TEAM <span id="teamLeft">0</span> •
    SCORE <span id="score">0</span>
  </div>

  <div class="box" id="stance">STANDING</div>

  <div class="box" id="hp"><div class="small">HEALTH</div><div class="bar"><div class="fill" id="hpf"></div></div></div>
  <div class="box" id="armorBox"><div class="small">ARMOR</div><div class="bar"><div class="fill" id="arf"></div></div></div>

  <div class="box" id="gun">
    <div id="ammo">30</div>
    <div id="gunname">PHANTOM-7</div>
    <div id="gunclass">ASSAULT RIFLE</div>
  </div>

  <div id="feed"></div>
</div>

<div id="end">
  <div class="endCard">
    <h1 id="endTitle" style="color:#8dffb0">OPERATION SUCCESS</h1>
    <div id="podium"></div>
    <p class="small" id="endText"></p>
    <button class="deploy" id="continueBtn" style="margin-top:20px">RETURN TO LOBBY</button>
  </div>
</div>

<script type="importmap">
{"imports":{
"three":"https://cdn.jsdelivr.net/npm/three@0.160.0/build/three.module.js",
"three/addons/":"https://cdn.jsdelivr.net/npm/three@0.160.0/examples/jsm/",
"peerjs":"https://esm.sh/peerjs@1.5.4"
}}
</script>

<script type="module">
import * as THREE from 'three';
import { PointerLockControls } from 'three/addons/controls/PointerLockControls.js';
import Peer from 'peerjs';

/* Save */
const save=Object.assign({
  credits:1500,primary:'rifle',secondary:'pistol',
  difficulty:'regular',mode:'assault',operator:'ranger'
},JSON.parse(localStorage.getItem('strikeOps20')||'{}'));

const persist=()=>localStorage.setItem('strikeOps20',JSON.stringify(save));

/* Renderer */
const renderer=new THREE.WebGLRenderer({antialias:true});
renderer.setSize(innerWidth,innerHeight);
renderer.setPixelRatio(Math.min(devicePixelRatio,1.5));
renderer.shadowMap.enabled=true;
renderer.shadowMap.type=THREE.PCFSoftShadowMap;
renderer.outputColorSpace=THREE.SRGBColorSpace;
document.body.appendChild(renderer.domElement);

const scene=new THREE.Scene();
const camera=new THREE.PerspectiveCamera(82,innerWidth/innerHeight,.08,450);
const controls=new PointerLockControls(camera,renderer.domElement);

scene.fog=new THREE.Fog(0xb8c9d6,65,180);

scene.add(new THREE.Mesh(
  new THREE.SphereGeometry(260,24,16),
  new THREE.ShaderMaterial({
    side:THREE.BackSide,
    uniforms:{
      top:{value:new THREE.Color(0x3f7fc4)},
      middle:{value:new THREE.Color(0x9fc8e8)},
      bottom:{value:new THREE.Color(0xe8d9b8)}
    },
    vertexShader:`varying vec3 vPos;void main(){vPos=position;gl_Position=projectionMatrix*modelViewMatrix*vec4(position,1.);}`,
    fragmentShader:`varying vec3 vPos;uniform vec3 top,middle,bottom;void main(){float h=normalize(vPos).y;vec3 c=mix(bottom,middle,smoothstep(-.1,.25,h));c=mix(c,top,smoothstep(.2,.75,h));gl_FragColor=vec4(c,1.);}`
  })
));

scene.add(new THREE.HemisphereLight(0xd8eaf8,0x6d655a,1.25));

const sun=new THREE.DirectionalLight(0xfff3d5,2.6);
sun.position.set(38,55,28);
sun.castShadow=true;
sun.shadow.mapSize.set(2048,2048);
sun.shadow.camera.left=-80;sun.shadow.camera.right=80;
sun.shadow.camera.top=80;sun.shadow.camera.bottom=-80;
sun.shadow.camera.far=200;
scene.add(sun);

/* Player */
const playerBody=new THREE.Object3D();
scene.add(playerBody);

const player={
  position:new THREE.Vector3(0,0,62),
  velocity:new THREE.Vector3(),
  hp:100,maxHp:100,armor:75,maxArmor:75,
  grounded:true,crouching:false,sliding:false,
  slideTime:0,slideDirection:new THREE.Vector3(),
  lean:0,leanTarget:0,aiming:false,
  standEye:1.68,crouchEye:1.05,
  radius:.42,kills:0
};

const MAP_LIMIT=70;
const keys={};

addEventListener('keydown',e=>{
  keys[e.code]=true;

  if(e.code==='KeyR')reload();
  if(e.code==='Digit1')equip(0);
  if(e.code==='Digit2')equip(1);

  if(e.code==='KeyC'){
    const moving=keys['KeyW']||keys['KeyA']||keys['KeyS']||keys['KeyD'];

    if(keys['ShiftLeft']&&moving&&player.grounded&&!player.sliding&&!player.crouching){
      player.sliding=true;
      player.slideTime=.9;

      const fwd=new THREE.Vector3();
      camera.getWorldDirection(fwd);
      fwd.y=0;fwd.normalize();

      player.slideDirection.copy(fwd);
    }

    player.crouching=true;
  }

  if(e.code==='KeyQ')player.leanTarget=-1;
  if(e.code==='KeyE')player.leanTarget=1;
  if(e.code==='KeyV')startKnife();
});

addEventListener('keyup',e=>{
  keys[e.code]=false;

  if(e.code==='KeyC')player.crouching=false;
  if(e.code==='KeyQ'&&player.leanTarget===-1)player.leanTarget=0;
  if(e.code==='KeyE'&&player.leanTarget===1)player.leanTarget=0;
});

addEventListener('mousedown',e=>{
  if(e.button===0)firing=true;
  if(e.button===2)player.aiming=true;
});

addEventListener('mouseup',e=>{
  if(e.button===0)firing=false;
  if(e.button===2)player.aiming=false;
});

addEventListener('contextmenu',e=>e.preventDefault());

/* Textures */
function texture(draw,repeat=[1,1]){
  const c=document.createElement('canvas');c.width=c.height=128;
  draw(c.getContext('2d'),128);

  const t=new THREE.CanvasTexture(c);
  t.wrapS=t.wrapT=THREE.RepeatWrapping;t.repeat.set(...repeat);
  t.colorSpace=THREE.SRGBColorSpace;
  return t;
}

function grain(g,s,a,n=2200){
  for(let i=0;i<n;i++){
    g.fillStyle=`rgba(255,255,255,${a})`;
    g.fillRect(Math.random()*s,Math.random()*s,2,2);
  }
}

const T={
  asphalt:texture((g,s)=>{g.fillStyle='#5d6267';g.fillRect(0,0,s,s);grain(g,s,.07)},[18,18]),
  concrete:texture((g,s)=>{g.fillStyle='#aaa69e';g.fillRect(0,0,s,s);grain(g,s,.06)},[6,6]),
  brick:texture((g,s)=>{
    g.fillStyle='#8d7963';g.fillRect(0,0,s,s);g.fillStyle='#a98a6c';
    for(let y=0;y<s;y+=16)for(let x=(y/16%2)*16;x<s;x+=32)g.fillRect(x+1,y+1,30,14);
  },[5,5]),
  metal:texture((g,s)=>{g.fillStyle='#75818c';g.fillRect(0,0,s,s);grain(g,s,.05)},[3,3]),
  wood:texture((g,s)=>{
    g.fillStyle='#8a6538';g.fillRect(0,0,s,s);
    for(let i=0;i<35;i++){
      g.strokeStyle='rgba(50,32,14,.2)';g.lineWidth=2;
      g.beginPath();g.moveTo(0,Math.random()*s);g.lineTo(s,Math.random()*s);g.stroke();
    }
  },[3,3])
};

function roadTexture(){
  return texture((g,s)=>{
    g.fillStyle='#3a3d41';g.fillRect(0,0,s,s);
    g.fillStyle='rgba(230,220,170,.75)';
    for(let y=8;y<s;y+=42)g.fillRect(s/2-3,y,6,22);
  },[1,16]);
}

function rustTexture(){
  return texture((g,s)=>{
    g.fillStyle='#7a5a3c';g.fillRect(0,0,s,s);
    for(let i=0;i<900;i++){
      g.fillStyle=`rgba(${120+Math.random()*70},60,25,${Math.random()*.5})`;
      g.beginPath();g.arc(Math.random()*s,Math.random()*s,Math.random()*7+1,0,Math.PI*2);g.fill();
    }
  },[2,2]);
}

function mat(t,color=0xffffff,rough=.85,metal=.04){
  const tx=t.clone();tx.needsUpdate=true;
  tx.wrapS=tx.wrapT=THREE.RepeatWrapping;
  return new THREE.MeshStandardMaterial({map:tx,color,roughness:rough,metalness:metal});
}

/* Map */
let world=new THREE.Group();
scene.add(world);

let walls=[],platforms=[],solidMeshes=[];
const spawnPoint=new THREE.Vector3(0,0,58);

function addSolid(o){
  world.add(o);
  walls.push(new THREE.Box3().setFromObject(o));
  solidMeshes.push(o);
}

function wall(x,y,z,w,h,d,m){
  const o=new THREE.Mesh(new THREE.BoxGeometry(w,h,d),m);
  o.position.set(x,y,z);o.castShadow=true;o.receiveShadow=true;
  addSolid(o);
}

function peekWall(x,y,z,w,h,d,m){
  wall(x,y,z,w,h,d,m);
}

function platform(x,y,z,w,d,m){
  const o=new THREE.Mesh(new THREE.BoxGeometry(w,.3,d),m);
  o.position.set(x,y-.15,z);o.receiveShadow=true;
  world.add(o);

  platforms.push(new THREE.Box3(
    new THREE.Vector3(x-w/2,y-.3,z-d/2),
    new THREE.Vector3(x+w/2,y,z+d/2)
  ));

  solidMeshes.push(o);
}

function cover(x,y,z,w,h,d,m){
  const o=new THREE.Mesh(new THREE.BoxGeometry(w,h,d),m);
  o.position.set(x,y+h/2,z);o.castShadow=true;o.receiveShadow=true;
  addSolid(o);
}

function stairs(x,z,direction,steps=10,h=.38,d=.85,width=4){
  const m=mat(T.concrete,0xd9d4c8,.86,0);

  for(let i=0;i<steps;i++){
    const off=i*d,y=(i+1)*h;

    if(direction==='west')platform(x-off,y,z,d,width,m);
    if(direction==='east')platform(x+off,y,z,d,width,m);
    if(direction==='north')platform(x,y,z-off,width,d,m);
    if(direction==='south')platform(x,y,z+off,width,d,m);
  }
}

function buildMap(){
  const ground=new THREE.Mesh(new THREE.PlaneGeometry(160,160),mat(T.asphalt,0xffffff,.94,0));
  ground.rotation.x=-Math.PI/2;ground.receiveShadow=true;world.add(ground);

  const roadMat=mat(roadTexture(),0xffffff,.82,0);
  const concrete=mat(T.concrete,0xcfc9bd,.87,0);
  const brick=mat(T.brick,0xffffff,.92,0);
  const metal=mat(T.metal,0x8a97a3,.48,.68);
  const wood=mat(T.wood,0xffffff,.88,0);

  const road=new THREE.Mesh(new THREE.PlaneGeometry(18,160),roadMat);
  road.rotation.x=-Math.PI/2;road.position.set(0,.012,0);road.receiveShadow=true;world.add(road);

  const crossRoad=new THREE.Mesh(new THREE.PlaneGeometry(160,16),roadMat);
  crossRoad.rotation.x=-Math.PI/2;crossRoad.position.set(0,.014,0);crossRoad.receiveShadow=true;world.add(crossRoad);

  /* Central plaza */
  platform(0,0,0,46,36,concrete);

  wall(0,2.3,-18,46,4.6,.6,brick);
  wall(0,2.3,18,46,4.6,.6,brick);
  wall(-23,2.3,0,.6,4.6,36,brick);
  wall(23,2.3,0,.6,4.6,36,brick);

  peekWall(-13,0,-5,8,1.15,.45,concrete);
  peekWall(13,0,-5,8,1.15,.45,concrete);
  peekWall(0,0,9,12,1.15,.45,concrete);
  peekWall(-19,0,9,7,1.15,.45,concrete);
  peekWall(19,0,9,7,1.15,.45,concrete);

  cover(-11,0,-10,5.5,2.3,2.8,wood);
  cover(11,0,-10,5.5,2.3,2.8,wood);

  platform(0,4.6,0,38,26,concrete);

  wall(0,5.6,-12.5,38,1,.3,concrete);
  wall(0,5.6,12.5,38,1,.3,concrete);
  wall(-18.75,5.6,0,.3,1,26,concrete);
  wall(18.75,5.6,0,.3,1,26,concrete);

  peekWall(-10,4.6,0,7,1.1,.4,concrete);
  peekWall(10,4.6,0,7,1.1,.4,concrete);

  stairs(27,0,'west',12,.38,.85,4);

  /* Buildings */
  function building(x,z,w,d,h,color){
    const wallMat=mat(T.brick,color,.9,0);

    wall(x,h/2,z-d/2,w,h,.6,wallMat);
    wall(x-w/2,h/2,z,.6,h,d,wallMat);
    wall(x+w/2,h/2,z,.6,h,d,wallMat);
    wall(x-w*.325,h/2,z+d/2,w*.35,h,.6,wallMat);
    wall(x+w*.325,h/2,z+d/2,w*.35,h,.6,wallMat);
    wall(x,h*.825,z+d/2,w*.3,h*.35,.6,wallMat);

    const roof=new THREE.Mesh(new THREE.BoxGeometry(w+.8,.5,d+.8),metal);
    roof.position.set(x,h+.25,z);roof.castShadow=true;world.add(roof);
  }

  building(-38,-42,28,22,11,0xb0a08a);
