/* Movement */
function eyeHeight(){
  return player.crouching?player.crouchEye:player.standEye;
}

function bodyHeight(){
  return player.crouching?1.15:1.72;
}

function groundHeightAt(x,z){
  let h=0;

  platforms.forEach(p=>{
    if(
      x>=p.min.x&&x<=p.max.x&&
      z>=p.min.z&&z<=p.max.z&&
      p.max.y<=player.position.y+1.3
    ){
      h=Math.max(h,p.max.y);
    }
  });

  return h;
}

function blockedAt(pos,height){
  const box=new THREE.Box3(
    new THREE.Vector3(pos.x-player.radius,pos.y+.25,pos.z-player.radius),
    new THREE.Vector3(pos.x+player.radius,pos.y+height,pos.z+player.radius)
  );

  return walls.some(w=>box.intersectsBox(w));
}

function move(dt){
  const w=weapons[current];

  let speed=6.5*w.moveSpeed;

  if(keys['ShiftLeft'])speed=10.2*w.moveSpeed;
  if(player.crouching&&!player.sliding)speed*=.5;
  if(player.sliding)speed=15.5;
  if(player.aiming)speed*=.55;

  const fwd=new THREE.Vector3();
  camera.getWorldDirection(fwd);
  fwd.y=0;fwd.normalize();

  const right=new THREE.Vector3().crossVectors(fwd,new THREE.Vector3(0,1,0)).normalize();
  const moveVector=new THREE.Vector3();

  if(!player.sliding){
    if(keys['KeyW'])moveVector.add(fwd);
    if(keys['KeyS'])moveVector.sub(fwd);
    if(keys['KeyD'])moveVector.add(right);
    if(keys['KeyA'])moveVector.sub(right);

    if(moveVector.lengthSq()>0){
      moveVector.normalize().multiplyScalar(speed*dt);
    }
  }else{
    moveVector.copy(player.slideDirection).multiplyScalar(speed*dt);
    player.slideTime-=dt;

    if(player.slideTime<=0){
      player.sliding=false;
    }
  }

  let next=player.position.clone();
  next.x+=moveVector.x;

  if(!blockedAt(next,bodyHeight())){
    player.position.x=next.x;
  }

  next=player.position.clone();
  next.z+=moveVector.z;

  if(!blockedAt(next,bodyHeight())){
    player.position.z=next.z;
  }

  const ground=groundHeightAt(player.position.x,player.position.z);

  player.velocity.y-=25*dt;
  player.position.y+=player.velocity.y*dt;

  if(player.position.y<=ground){
    player.position.y=ground;
    player.velocity.y=0;
    player.grounded=true;
  }

  if(keys['Space']&&player.grounded&&!player.crouching&&!player.sliding){
    player.velocity.y=9;
    player.grounded=false;
  }

  player.position.x=THREE.MathUtils.clamp(player.position.x,-MAP_LIMIT,MAP_LIMIT);
  player.position.z=THREE.MathUtils.clamp(player.position.z,-MAP_LIMIT,MAP_LIMIT);

  player.lean=THREE.MathUtils.lerp(player.lean,player.leanTarget,Math.min(1,dt*10));

  const cameraPosition=player.position.clone();
  cameraPosition.y+=eyeHeight();

  const peekOffset=right.clone().multiplyScalar(player.lean*.68);
  const peekPosition=cameraPosition.clone().add(peekOffset);
  peekPosition.y-=Math.abs(player.lean)*.14;

  camera.position.copy(peekPosition);

  const targetFov=player.aiming?52:82;
  camera.fov=THREE.MathUtils.lerp(camera.fov,targetFov,Math.min(1,dt*11));
  camera.updateProjectionMatrix();

  document.getElementById('crosshair').style.opacity=player.aiming?0:1;

  document.getElementById('stance').textContent=
    player.sliding?'SLIDING':
    player.crouching?'CROUCHED':
    player.aiming?'AIMING':
    player.leanTarget===-1?'PEEK LEFT':
    player.leanTarget===1?'PEEK RIGHT':
    keys['ShiftLeft']?'SPRINTING':'STANDING';
}

