/* Audio */
let audio,noiseBuffer;

function initAudio(){
  audio??=new AudioContext();
  if(noiseBuffer)return;

  const length=Math.floor(audio.sampleRate*.4);
  noiseBuffer=audio.createBuffer(1,length,audio.sampleRate);

  const data=noiseBuffer.getChannelData(0);
  for(let i=0;i<length;i++)data[i]=Math.random()*2-1;
}

function beep(f,d=.08,type='square',v=.07){
  initAudio();

  const o=audio.createOscillator(),g=audio.createGain();
  o.type=type;o.frequency.value=f;g.gain.value=v;
  o.connect(g);g.connect(audio.destination);o.start();
  g.gain.exponentialRampToValueAtTime(.0001,audio.currentTime+d);
  o.stop(audio.currentTime+d);
}

function gunshot(freq=900,d=.15,v=.24){
  initAudio();

  const src=audio.createBufferSource();src.buffer=noiseBuffer;
  const filter=audio.createBiquadFilter();filter.type='lowpass';filter.frequency.value=freq;
  const gain=audio.createGain();

  gain.gain.setValueAtTime(v,audio.currentTime);
  gain.gain.exponentialRampToValueAtTime(.0001,audio.currentTime+d);

  src.connect(filter);filter.connect(gain);gain.connect(audio.destination);
  src.start();src.stop(audio.currentTime+d);
}

/* Knife */
function startKnife(){
  if(knifeActive||knifeCooldown>0||reloading)return;

  knifeActive=true;
  knifeTime=.42;
  knifeCooldown=.8;
  knifeHitDone=false;

  viewmodel.userData.gunGroup.visible=false;
  viewmodel.userData.knifeGroup.visible=true;

  beep(320,.08,'triangle',.06);
  setTimeout(()=>beep(180,.09,'sawtooth',.05),130);
}

function updateKnife(dt){
  knifeCooldown=Math.max(0,knifeCooldown-dt);

  if(!knifeActive)return;

  knifeTime-=dt;

  const progress=1-Math.max(0,knifeTime/.42);
  const swipe=Math.sin(progress*Math.PI);

  const knife=viewmodel.userData.knifeGroup;

  knife.position.set(
    player.aiming?0:.2-swipe*.24,
    player.aiming?-.1:-.18+swipe*.1,
    player.aiming?-.3:-.32-swipe*.34
  );

  knife.rotation.set(
    .15-swipe*.5,
    -.35+swipe*.75,
    .2+swipe*.55
  );

  if(!knifeHitDone&&progress>.34){
    knifeHitDone=true;

    const forward=new THREE.Vector3();
    camera.getWorldDirection(forward);
    forward.y=0;forward.normalize();

    const right=new THREE.Vector3().crossVectors(forward,new THREE.Vector3(0,1,0)).normalize();

    const knifePoint=player.position.clone()
      .add(forward.clone().multiplyScalar(1.15))
      .add(right.clone().multiplyScalar(player.lean*.68));

    const targets=onlineOpponent
      ?[onlineOpponent]
      :bots.filter(b=>b.alive&&b.team==='enemy');

    targets.forEach(target=>{
      const center=target.g.position.clone();
      center.y+=1.2;

      const distance=knifePoint.distanceTo(center);

      if(distance<1.5){
        const toTarget=new THREE.Vector3()
          .subVectors(center,player.position)
          .setY(0)
          .normalize();

        if(forward.dot(toTarget)>.45){
          if(onlineOpponent){
            sendNet({t:'hit',damage:135,weapon:'KNIFE'});
          }else{
            target.hp-=135;

            spawnBlood(center,new THREE.Vector3(0,1,0),24);

            const hitEl=document.getElementById('hit');
            hitEl.style.opacity=1;
            setTimeout(()=>hitEl.style.opacity=0,80);

            beep(1250,.06,'sine',.06);

            if(target.hp<=0){
              target.alive=false;scene.remove(target.g);
              spawnBlood(center,new THREE.Vector3(0,1,0),34);

              save.credits+=230;score+=300;kills++;player.kills++;
              feed(`KNIFE ELIMINATED ${target.name} +CR230`);
              persist();updateHUD();
            }else{
              feed(`KNIFE HIT ${target.name} -135`);
            }
          }
        }
      }
    });
  }

  if(knifeTime<=0){
    knifeActive=false;
    viewmodel.userData.gunGroup.visible=true;
    viewmodel.userData.knifeGroup.visible=false;

    knife.position.set(.2,-.18,-.32);
    knife.rotation.set(.15,-.35,.2);
  }
}

