  const ring=new THREE.Mesh(new THREE.RingGeometry(.55,.72,32),new THREE.MeshBasicMaterial({color,transparent:true,opacity:.75,side:THREE.DoubleSide}));
  ring.raycast=()=>{};
  ring.rotation.x=-Math.PI/2;ring.position.y=.05;
  return ring;
}

/* Blood */
const bloodParticles=[],bloodDecals=[];
const bloodGeometry=new THREE.PlaneGeometry(.09,.09);

function spawnBlood(point,normal,amount=14){
  for(let i=0;i<amount;i++){
    const particle=new THREE.Mesh(bloodGeometry,new THREE.MeshBasicMaterial({
      color:new THREE.Color().setHSL(.99,1,.22+Math.random()*.12),
      transparent:true,opacity:.95,side:THREE.DoubleSide
    }));

    particle.position.copy(point);
    particle.rotation.set(Math.random()*Math.PI,Math.random()*Math.PI,Math.random()*Math.PI);

    scene.add(particle);

    bloodParticles.push({
      mesh:particle,
      velocity:new THREE.Vector3((Math.random()-.5)*4.5,Math.random()*3.2+.8,(Math.random()-.5)*4.5),
      life:.7+Math.random()*.4
    });
  }

  const splatterTexture=texture((g,s)=>{
    for(let i=0;i<22;i++){
      g.fillStyle=`rgba(${110+Math.random()*45},8,12,${.5+Math.random()*.4})`;
      g.beginPath();
      g.arc(s/2+(Math.random()-.5)*s*.55,s/2+(Math.random()-.5)*s*.55,Math.random()*13+3,0,Math.PI*2);
      g.fill();
    }
  },[1,1]);

  const splatter=new THREE.Mesh(
    new THREE.PlaneGeometry(.55+Math.random()*.45,.55+Math.random()*.45),
    new THREE.MeshBasicMaterial({map:splatterTexture,transparent:true,opacity:.92,depthWrite:false})
  );

  splatter.position.copy(point).add(normal.clone().multiplyScalar(.015));
  splatter.lookAt(point.clone().add(normal));
  splatter.rotateZ(Math.random()*Math.PI*2);
  splatter.raycast=()=>{};

  scene.add(splatter);
  bloodDecals.push({mesh:splatter,life:9+Math.random()*4});
}

function updateBlood(dt){
  for(let i=bloodParticles.length-1;i>=0;i--){
    const p=bloodParticles[i];
    p.life-=dt;p.velocity.y-=12*dt;
    p.mesh.position.addScaledVector(p.velocity,dt);
    p.mesh.rotation.x+=dt*8;p.mesh.rotation.y+=dt*6;
    p.mesh.material.opacity=Math.max(0,p.life/.8);

    if(p.mesh.position.y<.03){
      p.mesh.position.y=.03;p.velocity.set(0,0,0);
    }

    if(p.life<=0){
      scene.remove(p.mesh);p.mesh.material.dispose();
      bloodParticles.splice(i,1);
    }
  }

  for(let i=bloodDecals.length-1;i>=0;i--){
    const d=bloodDecals[i];
    d.life-=dt;

    if(d.life<2)d.mesh.material.opacity=Math.max(0,d.life/2*.92);

    if(d.life<=0){
      scene.remove(d.mesh);d.mesh.material.dispose();
      bloodDecals.splice(i,1);
    }
  }
}

/* Bots */
const difficultyCatalog={
  recruit:{name:'Recruit',enemyHp:80,accuracy:.28,reaction:1.7,squad:3,enemySquad:3},
  regular:{name:'Regular',enemyHp:100,accuracy:.42,reaction:1.15,squad:4,enemySquad:4},
  veteran:{name:'Veteran',enemyHp:125,accuracy:.56,reaction:.85,squad:5,enemySquad:5},
  elite:{name:'Elite',enemyHp:150,accuracy:.7,reaction:.55,squad:6,enemySquad:6}
};

const modeCatalog={
  assault:{name:'Squad Assault',desc:'Fight beside AI teammates against enemy soldiers.'},
  deathmatch:{name:'Bot Deathmatch',desc:'Continuous squad combat.'}
};

const bots=[];

function addBot(team,opId,nearPlayer=true){
  const s=soldier(opId);
  let x,z,tries=0;

  do{
    if(nearPlayer){
      const a=Math.random()*Math.PI*2,d=16+Math.random()*20;
      x=player.position.x+Math.cos(a)*d;
      z=player.position.z+Math.sin(a)*d;
    }else{
      x=(Math.random()*2-1)*55;
      z=(Math.random()*2-1)*55;
    }

    x=THREE.MathUtils.clamp(x,-55,55);
    z=THREE.MathUtils.clamp(z,-55,55);

    tries++;
  }while(tries<40&&(blockedAt(new THREE.Vector3(x,0,z),1.72)||Math.hypot(x-player.position.x,z-player.position.z)<12));

  s.g.position.set(x,groundHeightAt(x,z),z);
  s.g.userData.setTeamTint(team);

  const ally=team==='ally';
  const name=ally?`ALLY ${bots.filter(b=>b.team==='ally').length+1}`:`ENEMY ${bots.filter(b=>b.team==='enemy').length+1}`;

  s.g.add(makeNameTag(name,ally?'#8dffb0':'#ff5d5d'));
  s.g.add(makeTeamRing(ally?0x8dffb0:0xff5d5d));

  const D=difficultyCatalog[save.difficulty];

  bots.push({
    ...s,team,alive:true,name,
    hp:ally?110:D.enemyHp,
    speed:ally?3.5+Math.random():3+Math.random()*1.2,
    nextShot:0,awareness:0,
    weapon:['rifle','smg','shotgun','sniper','lmg','battleRifle','dmr'][Math.floor(Math.random()*7)]
  });

  scene.add(s.g);
}

function clearBots(){
  bots.forEach(b=>scene.remove(b.g));
  bots.length=0;
}

/* Combat */
const tracers=[],ray=new THREE.Raycaster(),losRay=new THREE.Raycaster();

function hasLineOfSight(from,to){
  const dir=to.clone().sub(from),distance=dir.length();
  dir.normalize();

  losRay.set(from,dir);losRay.far=distance-.45;

  return losRay.intersectObjects(solidMeshes,false).length===0;
}

function feed(text){
  const f=document.getElementById('feed');
  const d=document.createElement('div');
  d.className='feed';d.textContent=text;
  f.prepend(d);
  setTimeout(()=>d.remove(),3500);
}

function fireHitscan(){
  const w=weapons[current];

  const baseDir=new THREE.Vector3();
  camera.getWorldDirection(baseDir);

  let spread=w.spread;

  if(player.aiming)spread*=w.adsSpread;
  if(player.crouching)spread*=.55;
  if(player.sliding)spread*=2.6;
  if(!player.grounded)spread*=3;
  if(Math.abs(player.lean)>.4)spread*=1.15;

  for(let p=0;p<w.pellets;p++){
    const dir=baseDir.clone();
    dir.x+=(Math.random()-.5)*spread;
    dir.y+=(Math.random()-.5)*spread;
    dir.z+=(Math.random()-.5)*spread;
    dir.normalize();

    ray.set(camera.position.clone(),dir);
    ray.camera=camera;ray.far=w.range;

    let targets=[];

    if(onlineOpponent){
      targets=[onlineOpponent.g];
    }else{
      bots.forEach(b=>{if(b.alive&&b.team==='enemy')targets.push(b.g)});
    }

    const hit=ray.intersectObjects(targets,true)[0];
    const start=camera.position.clone().add(dir.clone().multiplyScalar(.65));
    let end=start.clone().add(dir.clone().multiplyScalar(w.range));

    if(hit){
      end=hit.point.clone();

      if(onlineOpponent&&hit.object.parent===onlineOpponent.g){
        sendNet({t:'hit',damage:w.damage,weapon:w.name});
      }else{
        const bot=bots.find(b=>b.g===hit.object.parent);

        if(bot){
          const headshot=hit.object===bot.head;
          const damage=headshot?w.damage*3.2:w.damage;

          bot.hp-=damage;

          const hitEl=document.getElementById('hit');
          hitEl.style.opacity=1;
          setTimeout(()=>hitEl.style.opacity=0,70);

          beep(headshot?1350:920,.045,'sine',.05);

          const normal=hit.face?hit.face.normal.clone().transformDirection(hit.object.matrixWorld):dir.clone().negate();
          spawnBlood(hit.point,normal,headshot?22:13);

          if(bot.hp<=0){
            bot.alive=false;scene.remove(bot.g);
            spawnBlood(hit.point,normal,30);

            save.credits+=headshot?190:115;
            score+=headshot?250:120;kills++;player.kills++;

            feed(`${headshot?'HEADSHOT':'ELIMINATED'} ${bot.name}`);
            persist();updateHUD();
          }else{
            feed(`${headshot?'HEADSHOT HIT':'HIT'} ${bot.name} -${Math.round(damage)}`);
          }
        }
      }
    }

    const line=new THREE.Line(
      new THREE.BufferGeometry().setFromPoints([start,end]),
      new THREE.LineBasicMaterial({color:0xffe38a,transparent:true,opacity:.7})
    );

    scene.add(line);
    tracers.push({line,life:.05});
  }
}

function shoot(){
  const now=performance.now()/1000,w=weapons[current];

  if(reloading||knifeActive||now-lastShot<w.fireRate)return;

  if(w.ammo<=0){reload();return;}

  lastShot=now;w.ammo--;
  recoil=Math.min(.25,recoil+w.recoil);
  viewmodel.userData.flash.intensity=20;

  updateHUD();gunshot(w.sound);
  fireHitscan();

  if(onlineOpponent){
    const dir=new THREE.Vector3();
    camera.getWorldDirection(dir);

    sendNet({
      t:'shot',
      origin:camera.position.toArray(),
      dir:dir.toArray(),
      weapon:w.name
    });
  }
}

function damagePlayer(n,fromPosition,attackerName='UNKNOWN ENEMY'){
  if(player.armor>0){
    const absorbed=Math.min(player.armor,n*.58);
    player.armor-=absorbed;n-=absorbed;
  }

  player.hp=Math.max(0,player.hp-n);updateHUD();

  const d=document.getElementById('dmg');
  d.style.opacity=.9;
  setTimeout(()=>d.style.opacity=0,100);

  feed(`HIT BY ${attackerName}`);

  if(fromPosition){
    const toEnemy=new THREE.Vector3().subVectors(fromPosition,player.position);
    const angle=Math.atan2(toEnemy.x,toEnemy.z);

    const forward=camera.getWorldDirection(new THREE.Vector3());
    const playerAngle=Math.atan2(forward.x,forward.z);

    const arrow=document.getElementById('damageArrow');
    arrow.style.transform=`translate(-50%,-50%) rotate(${(angle-playerAngle)*180/Math.PI}deg)`;
    arrow.style.opacity=1;

    clearTimeout(arrow._timer);
    arrow._timer=setTimeout(()=>arrow.style.opacity=0,750);
  }

  beep(130,.12,'sawtooth',.08);

  if(player.hp<=0){
    feed(`KILLED BY ${attackerName}`);

    if(onlineOpponent){
      sendNet({t:'died'});
      endOnlineMatch(false);
    }else{
      endMatch(false);
    }
  }
}

function botCombat(bot,dt){
  const enemyTargets=bots.filter(b=>b.alive&&b.team!==bot.team).map(b=>b.g.position);
  const targets=bot.team==='enemy'?[player.position,...enemyTargets]:enemyTargets;

  if(!targets.length)return;

  let target=targets[0],best=Infinity;

  targets.forEach(t=>{
    const d=bot.g.position.distanceTo(t);
    if(d<best){best=d;target=t;}
  });

  const botEye=bot.g.position.clone();botEye.y+=1.68;
  const targetEye=target.clone();targetEye.y+=1.55;

  const toTarget=new THREE.Vector3().subVectors(targetEye,botEye);
  const distance=toTarget.length();
  const direction=toTarget.clone().normalize();

  const forward=new THREE.Vector3(0,0,1).applyQuaternion(bot.g.quaternion);
  const facing=forward.dot(direction)>.15;

  const visible=hasLineOfSight(botEye,targetEye)&&facing&&distance<36;

  bot.awareness=visible?Math.min(1,bot.awareness+dt*1.7):Math.max(0,bot.awareness-dt*.8);

  const dir=new THREE.Vector3(target.x-bot.g.position.x,0,target.z-bot.g.position.z);
  const flatDistance=dir.length();dir.normalize();

  const preferredRange=bot.weapon==='shotgun'?9:bot.weapon==='sniper'||bot.weapon==='dmr'?40:18;

  if(!visible||flatDistance>preferredRange){
    const next=bot.g.position.clone().add(dir.multiplyScalar(bot.speed*dt));
    next.x=THREE.MathUtils.clamp(next.x,-MAP_LIMIT,MAP_LIMIT);
    next.z=THREE.MathUtils.clamp(next.z,-MAP_LIMIT,MAP_LIMIT);
    next.y=groundHeightAt(next.x,next.z);

    if(!blockedAt(next,1.72))bot.g.position.copy(next);
  }else if(flatDistance<preferredRange*.55){
    const next=bot.g.position.clone().sub(dir.multiplyScalar(bot.speed*.6*dt));
    next.x=THREE.MathUtils.clamp(next.x,-MAP_LIMIT,MAP_LIMIT);
    next.z=THREE.MathUtils.clamp(next.z,-MAP_LIMIT,MAP_LIMIT);
    next.y=groundHeightAt(next.x,next.z);

    if(!blockedAt(next,1.72))bot.g.position.copy(next);
  }

  bot.g.position.x=THREE.MathUtils.clamp(bot.g.position.x,-MAP_LIMIT,MAP_LIMIT);
  bot.g.position.z=THREE.MathUtils.clamp(bot.g.position.z,-MAP_LIMIT,MAP_LIMIT);

  const targetAngle=Math.atan2(target.x-bot.g.position.x,target.z-bot.g.position.z);
  let difference=targetAngle-bot.g.rotation.y;

  while(difference>Math.PI)difference-=Math.PI*2;
  while(difference<-Math.PI)difference+=Math.PI*2;

  bot.g.rotation.y+=difference*Math.min(1,dt*6);

  const moving=!visible||flatDistance>preferredRange;
  bot.phase+=dt*(moving?8.5:2.2);

  const swing=moving?Math.sin(bot.phase)*.48:Math.sin(bot.phase)*.04;
  const counter=Math.sin(bot.phase+Math.PI)*.48;

  bot.lUpperLeg.rotation.x=swing;
  bot.rUpperLeg.rotation.x=counter;
  bot.lLowerLeg.rotation.x=Math.max(0,-swing*.75);
  bot.rLowerLeg.rotation.x=Math.max(0,-counter*.75);
  bot.lUpper.rotation.x=counter*.45;
  bot.rUpper.rotation.x=swing*.45;
  bot.lLower.rotation.x=-.4;
  bot.rLower.rotation.x=-.4;

  const now=performance.now()/1000;
  const D=difficultyCatalog[save.difficulty];

  if(visible&&bot.awareness>=.95&&distance<32&&now-bot.nextShot>D.reaction+Math.random()*.5){
    bot.nextShot=now;

    if(Math.random()<D.accuracy){
      if(bot.team==='enemy'){
        damagePlayer(6+Math.random()*7,bot.g.position,bot.name);
      }else{
        const enemy=bots.find(b=>b.alive&&b.team==='enemy'&&b.g.position.distanceTo(bot.g.position)<30);

        if(enemy){
          enemy.hp-=22+Math.random()*14;

          if(enemy.hp<=0){
            enemy.alive=false;scene.remove(enemy.g);
            bot.kills++;

            feed(`${bot.name} ELIMINATION`);
            save.credits+=45;persist();updateHUD();
          }
        }
      }
    }

    gunshot(bot.team==='enemy'?820:900,.1,.1);
  }
}

/* Podium */
function showPodium(entries,title,color){
  const sorted=[...entries].sort((a,b)=>b.kills-a.kills).slice(0,3);

  const podium=document.getElementById('podium');
  podium.innerHTML='';

  const places=[
    {label:'2ND',class:'second',height:110},
    {label:'1ST',class:'first',height:150},
    {label:'3RD',class:'third',height:85}
  ];

  const order=[sorted[1],sorted[0],sorted[2]];

  order.forEach((entry,index)=>{
    if(!entry)return;

    const place=places[index];

    const spot=document.createElement('div');
    spot.className='podiumSpot';

    spot.innerHTML=`
      <div class="podiumName">${entry.name}</div>
      <div class="podiumKills">${entry.kills} kills</div>
      <div class="podiumBlock ${place.class}" style="height:${place.height}px">${place.label}</div>
    `;

    podium.append(spot);
  });

  document.getElementById('endTitle').textContent=title;
  document.getElementById('endTitle').style.color=color;
}

