/* Online multiplayer */
let peer=null,netConn=null,onlineOpponent=null,netCode='';
let netTimer=0;

function netStatus(text,color='#8dffb0'){
  const s=document.getElementById('netStatus');
  s.textContent=text;
  s.style.color=color;
}

function sendNet(data){
  if(netConn&&netConn.open){
    netConn.send(data);
  }
}

function createOnlineOpponent(){
  if(onlineOpponent)return;

  const model=soldier('urban');
  model.g.position.set(0,0,50);
  model.g.userData.setTeamTint('enemy');

  model.g.add(makeNameTag('OPPONENT','#ff5d5d'));
  model.g.add(makeTeamRing(0xff5d5d));

  scene.add(model.g);

  onlineOpponent={
    ...model,
    name:'OPPONENT',
    hp:100,
    targetPosition:new THREE.Vector3(0,0,50)
  };
}

function startOnlineMatch(){
  clearBots();
  createOnlineOpponent();

  onlineActive=true;roundActive=false;

  player.hp=100;player.armor=75;
  player.position.set(0,0,66);
  player.velocity.set(0,0,0);
  player.kills=0;

  knifeActive=false;knifeTime=0;knifeCooldown=0;

  weapons=[buildWeapon(save.primary),buildWeapon(save.secondary)];
  current=0;makeViewmodel(save.primary);

  document.getElementById('lobby').style.display='none';
  document.getElementById('end').style.display='none';
  document.getElementById('hud').style.display='block';

  updateHUD();
  controls.lock();
}

function endOnlineMatch(win){
  onlineActive=false;controls.unlock();

  const entries=[
    {name:'YOU',kills:player.kills},
    {name:'OPPONENT',kills:onlineOpponent?.kills||0}
  ];

  showPodium(entries,win?'VICTORY':'DEFEAT',win?'#8dffb0':'#ff5d5d');

  document.getElementById('endText').textContent=
    `Online duel • Join code ${netCode}`;

  document.getElementById('hud').style.display='none';
  document.getElementById('end').style.display='flex';
}

function handleNet(data){
  if(!data)return;

  if(data.t==='state'&&onlineOpponent){
    onlineOpponent.targetPosition.set(...data.p);
    onlineOpponent.g.position.lerp(onlineOpponent.targetPosition,.35);
    onlineOpponent.g.rotation.y=data.yaw;
  }

  if(data.t==='shot'){
    const origin=new THREE.Vector3(...data.origin);
    const dir=new THREE.Vector3(...data.dir);

    const start=origin.clone().add(dir.clone().multiplyScalar(.65));
    const end=start.clone().add(dir.clone().multiplyScalar(180));

    const line=new THREE.Line(
      new THREE.BufferGeometry().setFromPoints([start,end]),
      new THREE.LineBasicMaterial({color:0xffe38a,transparent:true,opacity:.7})
    );

    scene.add(line);
    tracers.push({line,life:.05});

    gunshot(900,.12,.14);
  }

  if(data.t==='hit'){
    damagePlayer(data.damage,onlineOpponent?.g.position,data.weapon||'OPPONENT');
  }

  if(data.t==='died'){
    if(onlineOpponent)onlineOpponent.kills++;
    endOnlineMatch(true);
  }
}

function setupConnection(connection){
  netConn=connection;

  connection.on('open',()=>{
    netStatus('CONNECTED — MATCH STARTING');
    startOnlineMatch();
  });

  connection.on('data',handleNet);

  connection.on('close',()=>{
    netStatus('OPPONENT DISCONNECTED','#ff5d5d');

    if(onlineActive){
      onlineActive=false;
      endOnlineMatch(true);
    }
  });
}

function randomCode(){
  const chars='ABCDEFGHJKLMNPQRSTUVWXYZ23456789';
  let code='';

  for(let i=0;i<6;i++)code+=chars[Math.floor(Math.random()*chars.length)];

  return code;
}

document.getElementById('hostBtn').onclick=()=>{
  netCode=randomCode();

  netStatus('CREATING MATCH...');

  peer=new Peer(`strike-ops-20-${netCode}`);

  peer.on('open',()=>{
    netStatus(`SHARE CODE: ${netCode}`,'#ffcc33');
  });

  peer.on('connection',connection=>{
    setupConnection(connection);
  });

  peer.on('error',()=>{
    netStatus('COULD NOT CREATE MATCH. TRY AGAIN.','#ff5d5d');
  });
};

document.getElementById('joinBtn').onclick=()=>{
  const code=document.getElementById('joinCode').value.trim().toUpperCase();

  if(!code){
    netStatus('ENTER A JOIN CODE','#ff5d5d');
    return;
  }

  netCode=code;

  netStatus('CONNECTING...');

  peer=new Peer();

  peer.on('open',()=>{
    const connection=peer.connect(`strike-ops-20-${code}`);
    setupConnection(connection);
  });

  peer.on('error',()=>{
    netStatus('INVALID CODE OR HOST OFFLINE','#ff5d5d');
  });
};

/* Match flow */
function deploy(){
  clearBots();

  bloodParticles.forEach(p=>scene.remove(p.mesh));bloodParticles.length=0;
  bloodDecals.forEach(d=>scene.remove(d.mesh));bloodDecals.length=0;

  if(onlineOpponent){
    scene.remove(onlineOpponent.g);
    onlineOpponent=null;
  }

  scene.remove(world);
  world=new THREE.Group();scene.add(world);
  walls=[];platforms=[];solidMeshes=[];

  buildMap();

  score=0;kills=0;round=1;
  player.hp=player.maxHp;player.armor=player.maxArmor;
  player.crouching=false;player.sliding=false;
  player.lean=0;player.leanTarget=0;player.aiming=false;
  player.velocity.set(0,0,0);
  player.position.copy(spawnPoint);
  player.kills=0;

  knifeActive=false;knifeTime=0;knifeCooldown=0;knifeHitDone=false;

  weapons=[buildWeapon(save.primary),buildWeapon(save.secondary)];
  current=0;makeViewmodel(save.primary);

  document.getElementById('lobby').style.display='none';
  document.getElementById('end').style.display='none';

  roundActive=true;

  const D=difficultyCatalog[save.difficulty];
  enemiesToSpawn=D.enemySquad;alliesToSpawn=D.squad-1;

  for(let i=0;i<D.enemySquad;i++){
    const ops=Object.keys(operatorCatalog);
    addBot('enemy',ops[Math.floor(Math.random()*ops.length)],true);
  }

  for(let i=0;i<D.squad-1;i++)addBot('ally',save.operator,true);

  document.getElementById('hud').style.display='block';
  updateHUD();
  controls.lock();
}

function endMatch(win){
  roundActive=false;controls.unlock();

  const D=difficultyCatalog[save.difficulty];
  const reward=Math.round((450+round*180)*D.reward);

  save.credits+=reward;persist();

  const entries=[
    {name:'YOU',kills:player.kills},
    ...bots.map(b=>({name:b.name,kills:b.kills}))
  ];

  showPodium(
    entries,
    win?'OPERATION SUCCESS':'MATCH LOST',
    win?'#8dffb0':'#ff5d5d'
  );

  document.getElementById('endText').textContent=
    `Redline District • ${D.name} • Round ${round} • Score ${score} • Bonus CR${reward}`;

  document.getElementById('hud').style.display='none';
  document.getElementById('end').style.display='flex';
}

document.getElementById('deployBtn').onclick=deploy;

document.getElementById('continueBtn').onclick=()=>{
  controls.unlock();
  document.getElementById('end').style.display='none';
  document.getElementById('hud').style.display='none';
  openLobby();
};

controls.addEventListener('unlock',()=>{
  if(roundActive&&player.hp>0&&!onlineActive)openLobby();
});

controls.addEventListener('lock',()=>{
  document.getElementById('lobby').style.display='none';
  document.getElementById('end').style.display='none';
});

/* HUD */
function updateHUD(){
  const w=weapons[current];

  document.getElementById('ammo').textContent=reloading?'--':w.ammo;
  document.getElementById('gunname').textContent=w.name;
  document.getElementById('gunclass').textContent=w.type;
  document.getElementById('hpf').style.width=(player.hp/player.maxHp*100)+'%';
  document.getElementById('arf').style.width=(player.armor/player.maxArmor*100)+'%';
  document.getElementById('round').textContent=round;
  document.getElementById('enemyLeft').textContent=
    onlineActive?(onlineOpponent?1:0):bots.filter(b=>b.alive&&b.team==='enemy').length+enemiesToSpawn;
  document.getElementById('teamLeft').textContent=
    onlineActive?1:bots.filter(b=>b.alive&&b.team==='ally').length+alliesToSpawn;
  document.getElementById('score').textContent=score;
  document.getElementById('hudCredits').textContent=save.credits;
}

/* Loop */
const clock=new THREE.Clock();

function animate(){
  requestAnimationFrame(animate);

  const dt=Math.min(clock.getDelta(),.05);

  if(document.getElementById('lobby').style.display!=='none'){
    renderer.setViewport(0,0,innerWidth,innerHeight);
    renderer.render(scene,camera);
    return;
  }

  if(onlineActive&&onlineOpponent){
    move(dt);

    const moving=keys['KeyW']||keys['KeyA']||keys['KeyS']||keys['KeyD'];
    updateViewmodel(dt,moving);

    if(firing&&!knifeActive)shoot();
    updateKnife(dt);

    netTimer-=dt;

    if(netTimer<=0){
      netTimer=.05;

      sendNet({
        t:'state',
        p:[player.position.x,player.position.y,player.position.z],
        yaw:camera.rotation.y
      });
    }
  }else if(controls.isLocked&&roundActive){
    move(dt);

    const moving=keys['KeyW']||keys['KeyA']||keys['KeyS']||keys['KeyD'];
    updateViewmodel(dt,moving);

    if(firing&&!knifeActive)shoot();
    updateKnife(dt);

    bots.forEach(b=>{if(b.alive)botCombat(b,dt);});

    const enemyAlive=bots.filter(b=>b.alive&&b.team==='enemy').length;
    const allyAlive=bots.filter(b=>b.alive&&b.team==='ally').length;

    if(enemyAlive<3&&enemiesToSpawn>0){
      const ops=Object.keys(operatorCatalog);
      addBot('enemy',ops[Math.floor(Math.random()*ops.length)],true);
      enemiesToSpawn--;updateHUD();
    }

    if(allyAlive<2&&alliesToSpawn>0){
      addBot('ally',save.operator,true);
      alliesToSpawn--;updateHUD();
    }

    if(enemyAlive===0&&enemiesToSpawn===0){
      round++;roundActive=false;endMatch(true);
    }
  }

  updateBlood(dt);

  for(let i=tracers.length-1;i>=0;i--){
    tracers[i].life-=dt;
    tracers[i].line.material.opacity=Math.max(0,tracers[i].life/.05);

    if(tracers[i].life<=0){
      scene.remove(tracers[i].line);
      tracers.splice(i,1);
    }
  }

  renderer.setViewport(0,0,innerWidth,innerHeight);
  renderer.render(scene,camera);
}

addEventListener('resize',()=>{
  camera.aspect=innerWidth/innerHeight;camera.updateProjectionMatrix();
  renderer.setSize(innerWidth,innerHeight);
});

openLobby();
animate();
</script>
</body>
